import {
  WEBRPC_SOURCE,
  isWebRpcError,
  WebRpcErrorCode,
  WebRpcConfigurationError,
  WebRpcProtocolError,
  WebRpcContractError,
  WebRpcTransportError,
  WebRpcChunkError
} from '@migaia/web-rpc'

try {
  await endpoint.send('server', 'add', { a: 1, b: 2 })
} catch (error) {
  if (isWebRpcError(error)) {
    switch (error.code) {
      case WebRpcErrorCode.deadlineExceeded:
        // 超时，由调用方按业务策略处理
        break
      case WebRpcErrorCode.authenticationFailed:
        // 鉴权失败，通常应提示配置问题
        break
      default:
